const require_index = require("./index.js");
const require_useNoInteractiveChildren = require("../../internal/useNoInteractiveChildren.js");
//#region src/components/FeatureFlags/useNoInteractiveChildrenForLabel.ts
/**
* Warn about interactive label content in v11 and enforce it in v12.
*/
const useNoInteractiveChildrenForLabel = (ref, message) => {
	const enableV12Release = require_index.useFeatureFlag("enable-v12-release");
	const migrationMessage = `${message}. Render interactive content as a sibling of the label or use the \`decorator\` prop when available`;
	require_useNoInteractiveChildren.useNoInteractiveChildren(ref, migrationMessage, { shouldThrow: enableV12Release });
};
//#endregion
exports.useNoInteractiveChildrenForLabel = useNoInteractiveChildrenForLabel;
